head.b:skin:
/* --------------------------------------------------------------------------
   LEXATRIP LUXURY TRAVEL BLOGGER THEME
   Brand Palette: Desert Gold, Sunset Amber, Royal Navy & Pure White
   -------------------------------------------------------------------------- */
:root {
  --primary: #FF6B00;
  --primary-dark: #E65100;
  --primary-light: #FFF3E0;
  --accent: #FFA000;
  --navy: #0F172A;
  --navy-light: #1E293B;
  --bg-page: #F8FAFC;
  --card-bg: #FFFFFF;
  --text-main: #1E293B;
  --text-muted: #64748B;
  --border: #E2E8F0;
  --radius-lg: 16px;
  --radius-md: 12px;
  --radius-sm: 8px;
  --shadow-sm: 0 2px 4px rgba(15, 23, 42, 0.05);
  --shadow-md: 0 8px 24px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 16px 32px rgba(255, 107, 0, 0.15);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Inter', 'Noto Sans Devanagari', -apple-system, sans-serif;
  background-color: var(--bg-page);
  color: var(--text-main);
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  padding-bottom: 75px; /* space for mobile bottom bar */
}

@media (min-width: 769px) {
  body { padding-bottom: 0; }
}

a { color: var(--primary); text-decoration: none; transition: all 0.2s ease; }
a:hover { color: var(--primary-dark); }

/* --------------------------------------------------------------------------
   TOP LUXURY HEADER
   -------------------------------------------------------------------------- */
.lexa-header {
  background: #FFFFFF;
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
}
.header-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 12px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.brand-logo-area {
  display: flex;
  align-items: center;
  gap: 12px;
  text-decoration: none;
}
.brand-icon {
  width: 44px;
  height: 44px;
  background: linear-gradient(135deg, #FF6B00 0%, #FF8F00 100%);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  font-size: 24px;
  box-shadow: 0 4px 12px rgba(255, 107, 0, 0.3);
}
.brand-logo-img {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  object-fit: cover;
  box-shadow: 0 4px 12px rgba(255, 107, 0, 0.25);
  border: 2px solid #FF6B00;
}
.brand-text-block h1 {
  font-family: 'Outfit', sans-serif;
  font-size: 22px;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: -0.5px;
  line-height: 1.1;
}
.brand-text-block span {
  font-size: 10px;
  font-weight: 700;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 1.2px;
  display: block;
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}
.header-call-btn {
  display: none;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  color: var(--navy);
  padding: 8px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
}
@media (min-width: 768px) {
  .header-call-btn { display: inline-flex; }
}
.header-book-btn {
  background: linear-gradient(135deg, #FF6B00 0%, #E65100 100%);
  color: #FFFFFF !important;
  font-family: 'Outfit', sans-serif;
  font-size: 14px;
  font-weight: 700;
  padding: 10px 20px;
  border-radius: 30px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 4px 14px rgba(255, 107, 0, 0.35);
  transition: transform 0.2s, box-shadow 0.2s;
}
.header-book-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 18px rgba(255, 107, 0, 0.45);
}

/* --------------------------------------------------------------------------
   HERO DESTINATION BANNER (Index Page)
   -------------------------------------------------------------------------- */
.hero-banner {
  background: linear-gradient(180deg, #0F172A 0%, #1E293B 100%);
  color: #FFFFFF;
  padding: 48px 20px 40px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.hero-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -20%;
  width: 140%;
  height: 200%;
  background: radial-gradient(circle, rgba(255,107,0,0.15) 0%, transparent 60%);
  pointer-events: none;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
  padding: 6px 16px;
  border-radius: 30px;
  font-size: 13px;
  font-weight: 600;
  color: var(--accent);
  margin-bottom: 16px;
  border: 1px solid rgba(255, 255, 255, 0.15);
}
.hero-title {
  font-family: 'Outfit', sans-serif;
  font-size: 32px;
  font-weight: 800;
  line-height: 1.25;
  margin-bottom: 14px;
  color: #FFFFFF;
}
@media (min-width: 768px) {
  .hero-title { font-size: 46px; }
}
.hero-desc {
  max-width: 680px;
  margin: 0 auto 24px;
  font-size: 16px;
  color: #CBD5E1;
}
.hero-cta-group {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  flex-wrap: wrap;
}
.btn-hero-primary {
  background: linear-gradient(135deg, #FF6B00 0%, #E65100 100%);
  color: #FFFFFF !important;
  font-weight: 700;
  padding: 12px 26px;
  border-radius: 30px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow: var(--shadow-lg);
}
.btn-hero-wa {
  background: #25D366;
  color: #FFFFFF !important;
  font-weight: 700;
  padding: 12px 24px;
  border-radius: 30px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 4px 14px rgba(37, 211, 102, 0.35);
}

/* --------------------------------------------------------------------------
   MAIN LAYOUT & CARDS
   -------------------------------------------------------------------------- */
.main-wrapper {
  max-width: 1140px;
  margin: 32px auto;
  padding: 0 20px;
}
.posts-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 28px;
}
@media (min-width: 768px) {
  .posts-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 1024px) {
  .posts-grid { grid-template-columns: repeat(3, 1fr); }
}

.post-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.25s, box-shadow 0.25s;
  display: flex;
  flex-direction: column;
}
.post-card:hover {
  transform: translateY(-5px);
  box-shadow: var(--shadow-md);
  border-color: rgba(255, 107, 0, 0.3);
}
.card-media {
  width: 100%;
  height: 220px;
  object-fit: cover;
  background-color: var(--navy-light);
}
.card-body {
  padding: 22px;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}
.card-badge {
  align-self: flex-start;
  background: var(--primary-light);
  color: var(--primary-dark);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 20px;
  margin-bottom: 12px;
}
.card-title {
  font-family: 'Outfit', sans-serif;
  font-size: 19px;
  font-weight: 700;
  line-height: 1.35;
  color: var(--navy);
  margin-bottom: 10px;
}
.card-excerpt {
  font-size: 14px;
  color: var(--text-muted);
  line-height: 1.6;
  margin-bottom: 18px;
  flex-grow: 1;
}
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 14px;
  border-top: 1px solid var(--border);
  font-size: 13px;
  color: var(--text-muted);
}
.card-read-link {
  font-weight: 700;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

/* --------------------------------------------------------------------------
   SINGLE POST / ARTICLE STYLING
   -------------------------------------------------------------------------- */
.article-container {
  max-width: 820px;
  margin: 20px auto 40px;
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-sm);
  padding: 24px;
  overflow: hidden;
}
@media (min-width: 768px) {
  .article-container { padding: 44px; margin-top: 36px; }
}
.article-category {
  display: inline-block;
  background: var(--primary-light);
  color: var(--primary-dark);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  padding: 5px 14px;
  border-radius: 30px;
  margin-bottom: 14px;
}
.article-title {
  font-family: 'Outfit', sans-serif;
  font-size: 26px;
  font-weight: 800;
  line-height: 1.3;
  color: var(--navy);
  margin-bottom: 16px;
}
@media (min-width: 768px) {
  .article-title { font-size: 36px; }
}
.article-meta {
  display: flex;
  align-items: center;
  gap: 14px;
  padding-bottom: 20px;
  margin-bottom: 28px;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  color: var(--text-muted);
  flex-wrap: wrap;
}
.author-badge {
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
  color: var(--navy);
}
.author-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--primary);
  color: #FFF;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
}

/* Article Content */
.article-content {
  font-size: 17px;
  line-height: 1.85;
  color: #2D3748;
}
.article-content p {
  margin-bottom: 22px;
}
.article-content h2, .article-content h3 {
  font-family: 'Outfit', sans-serif;
  color: var(--navy);
  font-weight: 700;
  margin: 36px 0 16px;
  line-height: 1.3;
}
.article-content h2 { font-size: 24px; border-left: 4px solid var(--primary); padding-left: 14px; }
.article-content h3 { font-size: 20px; }
.article-content img {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius-md);
  margin: 24px 0;
  box-shadow: var(--shadow-sm);
}
.article-content blockquote {
  background: var(--primary-light);
  border-left: 4px solid var(--primary);
  padding: 18px 22px;
  margin: 26px 0;
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  font-style: italic;
  color: var(--navy);
  font-size: 18px;
}
.article-content ul, .article-content ol {
  margin: 20px 0 24px 26px;
}
.article-content li {
  margin-bottom: 10px;
}

/* In-Article High Conversion Box */
.in-article-cta {
  background: linear-gradient(135deg, #FFF8F0 0%, #FFF3E6 100%);
  border: 2px dashed #FF6B00;
  border-radius: var(--radius-lg);
  padding: 26px;
  margin: 34px 0;
  text-align: center;
}
.in-article-cta h3 {
  font-family: 'Outfit', sans-serif;
  color: var(--navy);
  font-size: 22px;
  margin-bottom: 10px;
  margin-top: 0;
}
.in-article-cta p {
  font-size: 15px;
  color: var(--text-muted);
  margin-bottom: 20px;
}
.cta-buttons-row {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}
.btn-cta-wa {
  background: #25D366;
  color: #FFFFFF !important;
  font-weight: 700;
  padding: 12px 24px;
  border-radius: 30px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  box-shadow: 0 4px 12px rgba(37, 211, 102, 0.3);
}
.btn-cta-book {
  background: var(--navy);
  color: #FFFFFF !important;
  font-weight: 700;
  padding: 12px 24px;
  border-radius: 30px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

/* Social Share Bar */
.share-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 0;
  margin-top: 36px;
  border-top: 1px solid var(--border);
  flex-wrap: wrap;
}
.share-label {
  font-weight: 700;
  font-size: 14px;
  color: var(--navy);
}
.btn-share {
  padding: 8px 16px;
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
  color: #FFF !important;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.btn-share-wa { background: #25D366; }
.btn-share-fb { background: #1877F2; }
.btn-share-tg { background: #0088CC; }

/* --------------------------------------------------------------------------
   PERSISTENT MOBILE ACTION BAR (Sticky Bottom)
   -------------------------------------------------------------------------- */
.mobile-bottom-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-top: 1px solid var(--border);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  z-index: 9998;
  box-shadow: 0 -4px 16px rgba(15, 23, 42, 0.08);
}
@media (min-width: 769px) {
  .mobile-bottom-bar { display: none; }
}
.mob-btn {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 8px 4px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-weight: 700;
  text-align: center;
  line-height: 1.2;
  gap: 3px;
}
.mob-btn-call {
  background: #F1F5F9;
  color: var(--navy) !important;
}
.mob-btn-wa {
  background: #E8F8EE;
  color: #128C7E !important;
}
.mob-btn-book {
  background: linear-gradient(135deg, #FF6B00 0%, #E65100 100%);
  color: #FFFFFF !important;
  box-shadow: 0 4px 10px rgba(255, 107, 0, 0.3);
}

/* --------------------------------------------------------------------------
   FLOATING WHATSAPP & OFFER WIDGETS
   -------------------------------------------------------------------------- */
.floating-wa-btn {
  position: fixed;
  bottom: 85px;
  right: 20px;
  background: #25D366;
  color: #FFFFFF !important;
  width: 58px;
  height: 58px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  box-shadow: 0 8px 24px rgba(37, 211, 102, 0.45);
  z-index: 9997;
  transition: transform 0.25s, box-shadow 0.25s;
  animation: pulse-wa 2.5s infinite;
}
@media (min-width: 769px) {
  .floating-wa-btn { bottom: 30px; width: 62px; height: 62px; }
}
.floating-wa-btn:hover {
  transform: scale(1.08);
  box-shadow: 0 12px 28px rgba(37, 211, 102, 0.6);
}
@keyframes pulse-wa {
  0% { box-shadow: 0 0 0 0 rgba(37, 211, 102, 0.5); }
  70% { box-shadow: 0 0 0 16px rgba(37, 211, 102, 0); }
  100% { box-shadow: 0 0 0 0 rgba(37, 211, 102, 0); }
}

/* Floating Offer Gift Pill */
.floating-offer-pill {
  position: fixed;
  bottom: 155px;
  right: 20px;
  background: linear-gradient(135deg, #FF6B00 0%, #FFA000 100%);
  color: #FFFFFF !important;
  padding: 10px 18px;
  border-radius: 30px;
  font-weight: 700;
  font-size: 13px;
  display: flex;
  align-items: center;
  gap: 8px;
  box-shadow: var(--shadow-lg);
  z-index: 9996;
  cursor: pointer;
  border: 2px solid #FFFFFF;
  transition: transform 0.2s;
}
@media (min-width: 769px) {
  .floating-offer-pill { bottom: 105px; }
}
.floating-offer-pill:hover { transform: scale(1.05); }

/* --------------------------------------------------------------------------
   EXCLUSIVE OFFER LEAD CAPTURE MODAL (हल्का सा फॉर्म)
   -------------------------------------------------------------------------- */
.offer-modal-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(15, 23, 42, 0.7);
  backdrop-filter: blur(6px);
  display: none;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 99999;
}
.offer-modal-overlay.active { display: flex; }
.offer-modal {
  background: #FFFFFF;
  border-radius: var(--radius-lg);
  max-width: 460px;
  width: 100%;
  padding: 30px 26px;
  position: relative;
  box-shadow: 0 24px 48px rgba(0,0,0,0.25);
  animation: modal-enter 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes modal-enter {
  from { opacity: 0; transform: scale(0.92) translateY(20px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}
.modal-close-btn {
  position: absolute;
  top: 16px;
  right: 18px;
  background: #F1F5F9;
  border: none;
  font-size: 20px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  cursor: pointer;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
}
.modal-badge {
  background: var(--primary-light);
  color: var(--primary-dark);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 20px;
  display: inline-block;
  margin-bottom: 12px;
}
.modal-title {
  font-family: 'Outfit', sans-serif;
  font-size: 22px;
  font-weight: 800;
  color: var(--navy);
  line-height: 1.25;
  margin-bottom: 8px;
}
.modal-desc {
  font-size: 14px;
  color: var(--text-muted);
  margin-bottom: 20px;
  line-height: 1.5;
}
.form-group {
  margin-bottom: 14px;
  text-align: left;
}
.form-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 6px;
}
.form-input {
  width: 100%;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-family: inherit;
  transition: border-color 0.2s;
}
.form-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(255, 107, 0, 0.15);
}
.modal-submit-btn {
  width: 100%;
  background: linear-gradient(135deg, #FF6B00 0%, #E65100 100%);
  color: #FFFFFF;
  font-family: 'Outfit', sans-serif;
  font-size: 16px;
  font-weight: 700;
  padding: 14px;
  border: none;
  border-radius: 30px;
  cursor: pointer;
  box-shadow: var(--shadow-lg);
  margin-top: 8px;
  transition: transform 0.2s;
}
.modal-submit-btn:hover { transform: translateY(-2px); }
.modal-disclaimer {
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  margin-top: 12px;
}

/* --------------------------------------------------------------------------
   LUXURY FOOTER
   -------------------------------------------------------------------------- */
.lexa-footer {
  background: var(--navy);
  color: #CBD5E1;
  padding: 48px 20px 30px;
  margin-top: 60px;
}
.footer-container {
  max-width: 1140px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr;
  gap: 36px;
}
@media (min-width: 768px) {
  .footer-container { grid-template-columns: 2fr 1fr 1fr; }
}
.footer-brand h3 {
  font-family: 'Outfit', sans-serif;
  font-size: 22px;
  font-weight: 800;
  color: #FFFFFF;
  margin-bottom: 12px;
}
.footer-brand p {
  font-size: 14px;
  line-height: 1.7;
  margin-bottom: 18px;
}
.footer-heading {
  font-family: 'Outfit', sans-serif;
  color: #FFFFFF;
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 16px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.footer-links {
  list-style: none;
}
.footer-links li {
  margin-bottom: 10px;
  font-size: 14px;
}
.footer-links a {
  color: #94A3B8;
}
.footer-links a:hover {
  color: var(--primary);
}
.footer-bottom {
  max-width: 1140px;
  margin: 40px auto 0;
  padding-top: 24px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  text-align: center;
  font-size: 13px;
  color: #64748B;
}

body.script:
//
function openOfferModal() {
  const modal = document.getElementById('offerModal');
  if (modal) modal.classList.add('active');
}

function closeOfferModal() {
  const modal = document.getElementById('offerModal');
  if (modal) modal.classList.remove('active');
}

function handleOverlayClick(e) {
  if (e.target.id === 'offerModal') closeOfferModal();
}

// Auto-open modal after 18 seconds if not opened before
setTimeout(function() {
  if (!sessionStorage.getItem('offerModalShown')) {
    openOfferModal();
    sessionStorage.setItem('offerModalShown', 'true');
  }
}, 18000);

// Form submission handler
async function handleLeadSubmit(e) {
  e.preventDefault();
  const name = document.getElementById('guestName').value.trim();
  const phone = document.getElementById('guestPhone').value.trim();
  const email = document.getElementById('guestEmail').value.trim();
  const travelDate = document.getElementById('travelDate').value;

  const promoCode = 'LEXA50ACTIVE';

  // 1. Send lead asynchronously to LexaTrip Automation API
  try {
    fetch('https://lexa-trip-automation.onrender.com/api/crm/lead', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: name,
        phone: phone,
        email: email,
        destination: 'Jaisalmer',
        travelDate: travelDate,
        promoCode: promoCode,
        source: 'Blogger Website Form',
        sourceUrl: window.location.href
      })
    }).catch(function(err){ console.log('Lead sync noted'); });
  } catch (err) {}

  // 2. Prepare WhatsApp direct redirect with pre-filled guest details
  const waText = encodeURIComponent(
    'नमस्ते LexaTrip! मैंने डिस्काउंट कूपन फॉर्म सबमिट किया है।\n' +
    '👤 नाम: ' + name + '\n' +
    '📱 WhatsApp: ' + phone + '\n' +
    (email ? '📧 ईमेल: ' + email + '\n' : '') +
    (travelDate ? '📅 यात्रा तारीख: ' + travelDate + '\n' : '') +
    '🎟️ कूपन कोड: ' + promoCode + ' (50% Off)\n' +
    'कृपया मुझे जैसलमेर के बेस्ट कैंप्स और पैकेजेस की जानकारी भेजें!'
  );

  // Close modal and redirect to WhatsApp
  closeOfferModal();
  alert('🎉 बधाई हो ' + name + '! आपका 50% डिस्काउंट कूपन ' + promoCode + ' अनलॉक हो गया है। अब आपको WhatsApp पर कनेक्ट किया जा रहा है...');
  window.open('https://wa.me/919079854982?text=' + waText, '_blank');
}
